public class Empleado {
    static int totalEmpleados = 0;
    static double totalSalarios = 0;
    String nombre;
    String cargo;
    double salarioBase;
    double bono;

    Empleado(String nombre, String cargo, double salarioBase, double bono) {
        this.nombre = nombre;
        this.cargo = cargo;
        this.salarioBase = salarioBase;
        this.bono = bono;
        totalEmpleados++;
        totalSalarios += calcularSueldo();
    }

    double calcularSueldo() {
        return salarioBase + bono;
    }

    void mostrarSueldo() {
        System.out.println(nombre + " (" + cargo + ") - Sueldo: $" + calcularSueldo());
    }

    static double promedioSueldo() {
        return totalSalarios / totalEmpleados;
    }

    public static void main(String[] args) {
        Empleado e1 = new Empleado("Ana", "Desarrolladora", 2500, 500);
        Empleado e2 = new Empleado("Luis", "Diseñador", 2200, 300);
        Empleado e3 = new Empleado("María", "Líder", 3500, 800);
        e1.mostrarSueldo();
        e2.mostrarSueldo();
        e3.mostrarSueldo();
        System.out.println("Promedio: $" + Empleado.promedioSueldo());
    }
}
